/* v8 composition */
.s-game_section{background:radial-gradient(circle at 50% 10%,#27316b 0,#101735 44%,#080d24 100%)}
.s-game_section__head{padding-top:14px}
.s-game_section__head h2{font-size:clamp(1.85rem,8vw,2.8rem);text-wrap:balance}
.s-game_section__head p{max-width:420px;color:#e0e5ff}
.s-game_section__frame{isolation:isolate}
.s-game_section__frame:after{content:"";position:absolute;inset:0;pointer-events:none;z-index:4;box-shadow:inset 0 0 42px rgba(5,8,27,.62),inset 0 -50px 70px rgba(5,8,27,.22)}
.s-game_section__stats{justify-content:space-between}
.s-game_section__stats span{min-width:104px;text-align:center;background:rgba(10,16,47,.82);box-shadow:0 5px 15px rgba(0,0,0,.18)}
.s-game_section__prompt{animation:lexPrompt 1.2s ease-in-out infinite}
.s-game_section__modal{background:linear-gradient(180deg,#283266,#151b42);border-color:#ffe092}
.s-game_section__framephoto{height:190px}
.s-game_section__pair{position:relative;justify-content:center;min-height:145px;margin-top:12px}
.s-game_section__pair img{width:46%;height:145px;box-shadow:0 12px 25px rgba(0,0,0,.24)}
.s-game_section__pair img:first-child{transform:rotate(-2deg) translateX(5px)}
.s-game_section__pair img:last-child{transform:rotate(2deg) translateX(-5px)}
.s-game_section__ticket{position:relative;margin:16px 0;padding:18px 16px;background:linear-gradient(135deg,#fff3c5,#f5c86d);border:2px solid #fff7dc;border-radius:15px;color:#20264f;box-shadow:0 8px 0 #9d6237,0 17px 32px rgba(0,0,0,.25);text-align:center}
.s-game_section__ticket:before,.s-game_section__ticket:after{content:"";position:absolute;top:50%;width:18px;height:36px;margin-top:-18px;border-radius:50%;background:#202752}
.s-game_section__ticket:before{left:-11px}.s-game_section__ticket:after{right:-11px}
.s-game_section__ticket>span{font:900 .57rem var(--font-body);letter-spacing:.2em;color:#9d3252}
.s-game_section__ticket strong{display:block;margin:5px 0;font:700 1.35rem/1 var(--font-title)}
.s-game_section__ticket p{margin:7px 0 0!important;color:#34406c!important;font-size:.8rem!important}
.s-game_section__ticket small{font-size:.72rem}
.s-game_section__calendar{display:flex;align-items:center;justify-content:center;gap:8px;min-height:48px;margin-top:18px;padding:12px 14px;border:2px solid #aee4c0;border-radius:13px;background:#1e7449;color:#fff;font:900 .68rem/1.25 var(--font-body);letter-spacing:.1em;text-align:center;text-decoration:none;box-shadow:0 5px 0 #0f472c;transition:transform 160ms ease,box-shadow 160ms ease}
.s-game_section__calendar:focus-visible{outline:3px solid #fff;outline-offset:3px}
.s-game_section__calendar:active{transform:translateY(3px);box-shadow:0 2px 0 #0f472c}
.s-game_section__calendarNote{margin:9px auto 0!important;max-width:320px;text-align:center;font-size:.7rem!important;color:#bfc9f5!important}
.s-game_section__wishesTitle{margin-top:26px!important}
@keyframes lexPrompt{50%{transform:translateX(-50%) translateY(-3px)}}
@media(hover:hover) and (pointer:fine){.s-game_section__calendar:hover{transform:translateY(-2px);box-shadow:0 7px 0 #0f472c}}
@media(prefers-reduced-motion:reduce){.s-game_section__prompt{animation:none}.s-game_section__calendar{transition:none}.s-game_section__pair img{transform:none}}
